def test_add_tracefuncs(he_pm: PluginManager) -> None:
    out: list[Any] = []

    class api1:
        @hookimpl
        def he_method1(self):
            out.append("he_method1-api1")

    class api2:
        @hookimpl
        def he_method1(self):
            out.append("he_method1-api2")

    he_pm.register(api1())
    he_pm.register(api2())

    def before(hook_name, hook_impls, kwargs):
        out.append((hook_name, list(hook_impls), kwargs))

    def after(outcome, hook_name, hook_impls, kwargs):
        out.append((outcome, hook_name, list(hook_impls), kwargs))

    undo = he_pm.add_hookcall_monitoring(before, after)

    he_pm.hook.he_method1(arg=1)
    assert len(out) == 4
    assert out[0][0] == "he_method1"
    assert len(out[0][1]) == 2
    assert isinstance(out[0][2], dict)
    assert out[1] == "he_method1-api2"
    assert out[2] == "he_method1-api1"
    assert len(out[3]) == 4
    assert out[3][1] == out[0][0]

    undo()
    he_pm.hook.he_method1(arg=1)
    assert len(out) == 4 + 2

def test_dbl_plugin_tracing(pm: PluginManager) -> None:
    class Api:
        @hookspec
        def hello(self, arg: object) -> None:
            "api hook 1"

    pm.add_hookspecs(Api)
    hook = pm.hook
    test_hc = hook.hello

    class Plugin:
        @hookimpl
        def hello(self, arg):
            return arg + 1

        @hookimpl(specname="hello")
        def hello_again(self, arg):
            return arg + 100

    plugin = Plugin()

    trace_out: list[str] = []
    pm.trace.root.setwriter(trace_out.append)
    pm.register(plugin)
    pm.enable_tracing()

    out = test_hc(arg=3)
    assert out == [103, 4]

    assert trace_out == [
        "  hello [hook]\n      arg: 3\n",
        "  finish hello --> [103, 4] [hook]\n",
    ]

    trace_out.clear()
    pm.unregister(plugin)
    out = test_hc(arg=3)
    assert out == []

    assert trace_out == [
        "  hello [hook]\n      arg: 3\n",
        "  finish hello --> [] [hook]\n",
    ]
